 const bottle=new T.Group();bottle.position.set(2.5,.75,-.4);scene.add(bottle);cyl(.25,.9,ivory,0,.46,0,bottle);cyl(.17,.15,gold,0,.98,0,bottle);box(.27,.35,.04,teal,0,.46,.245,bottle);targets.set('milk',bottle);
