 const navStyle=document.createElement('style');navStyle.textContent='body.coffee-open #world-navigation,body.coffee-open #overland-view-toggle,body.coffee-open #overland-view-drawer{visibility:hidden}#coffee-places-list{display:grid;gap:6px;margin-top:8px;max-width:170px}#coffee-places-list[hidden]{display:none}.coffee-views{display:grid;gap:4px;border-bottom:1px solid #c9bea5;padding-bottom:12px;margin-bottom:12px}#coffee-station button[aria-pressed=true]{background:#743d50;color:#fff;box-shadow:inset 0 0 0 2px #567c66}#coffee-station button[aria-pressed=false]{background:#fff9e9;color:#354e47}';document.head.append(navStyle);
 function focus(view){if(!opened)throw Error('Open the coffee shop first');if(!['shop','counter'].includes(view))throw Error('Unknown coffee view');roomView=view;room.shell.visible=view==='shop';resize();$('coffee-room-view').setAttribute('aria-pressed',String(view==='shop'));$('coffee-counter-view').setAttribute('aria-pressed',String(view==='counter'));changed();return read();}
