 let voice=true;function speak(text){return;}
 function read(){return {open:opened,level:1,view:roomView,room:room.report,camera:{position:camera.position.toArray(),target:orbit.target.toArray()},humanHexes:room.grid.visible,...state,stepName:state.served?'done':STEPS[state.step].id,recipe:DRINKS[state.drink],animating:!!animation,narration:voice,revision};}
 function changed(){revision++;window.RanchView?.changed();}
