 function renderUI(){visual();const step=STEPS[state.step];$('coffee-drink').textContent=DRINKS[state.drink].name;$('coffee-progress').innerHTML=STEPS.map((s,i)=>`<span class="${i<state.step||state.served?'done':''}" ${i===state.step&&!state.served?'aria-current="step"':''} aria-label="${s.label}">${i<state.step||state.served?'✓':s.icon}</span>`).join('');$('coffee-prompt').textContent=state.served?'Yummy! ♡':step.label;$('coffee-do').textContent=step.icon+' '+step.label;$('coffee-do').hidden=state.served;$('coffee-do').disabled=!!animation;$('coffee-again').hidden=!state.served;panel.querySelector('.foam').style.height=(DRINKS[state.drink].foam*100)+'%';ring.visible=false;if(ring.visible){const obj=targets.get(step.id);ring.position.copy(obj.position);ring.position.y+=step.id==='cup'?.08:step.id==='milk'?1.1:step.id==='pour'?.75:0;ring.rotation.x=['brew','steam'].includes(step.id)?0:Math.PI/2;ring.position.z+=step.id==='brew'?.12:step.id==='steam'?.35:0;}}
 function hint(){speak(state.served?'You made a lovely coffee! Tap Again to make another.':STEPS[state.step].hint);return read();}
