 $('coffee-back').onclick=()=>close('square');$('coffee-overland').onclick=()=>close('world');$('coffee-places').onclick=()=>{const list=$('coffee-places-list');list.hidden=!list.hidden;$('coffee-places').setAttribute('aria-expanded',String(!list.hidden));};$('coffee-room-view').onclick=()=>focus('shop');$('coffee-counter-view').onclick=()=>focus('counter');$('coffee-hex-view').onclick=()=>setHexes(!room.grid.visible);$('coffee-do').onclick=()=>act(STEPS[state.step].id);$('coffee-hint').onclick=hint;$('coffee-again').onclick=again;$('coffee-voice').onclick=()=>{voice=!voice;$('coffee-voice').setAttribute('aria-pressed',String(voice));$('coffee-voice').textContent=voice?'🔊 Voice':'🔇 Voice';if(!voice)window.speechSynthesis?.cancel();else hint();changed();};$('coffee-drawer-toggle').onclick=()=>{const d=$('coffee-drawer');d.hidden=!d.hidden;panel.classList.toggle('drawer-closed',d.hidden);$('coffee-drawer-toggle').setAttribute('aria-expanded',String(!d.hidden));resize();};panel.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const buttons=[...panel.querySelectorAll('button')].filter(b=>!b.disabled&&b.getClientRects().length),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 const ray=new T.Raycaster(),pointer=new T.Vector2();let down=null;
