 function resize(){if(!opened)return;const {width,height}=stage.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;if(roomView==='shop'){const target=new T.Vector3(0,1,0),direction=new T.Vector3(10,13,17).normalize();let distance=13;for(let i=0;i<35;i++){camera.position.copy(target).addScaledVector(direction,distance);camera.lookAt(target);orbit.target.copy(target);camera.updateProjectionMatrix();camera.updateMatrixWorld();const corners=[];for(const x of [-6.3,6.3])for(const y of [-.35,3.6])for(const z of [-5.3,5.3])corners.push(new T.Vector3(x,y,z).project(camera));if(corners.every(p=>Math.abs(p.x)<.88&&p.y<.77&&p.y>-.83))break;distance*=1.07;}}else{const bounds=new T.Box3().setFromObject(apparatus),target=bounds.getCenter(new T.Vector3()),direction=new T.Vector3(-2.1,2.8,-3.2).normalize();let distance=2.5;for(let i=0;i<32;i++){camera.position.copy(target).addScaledVector(direction,distance);camera.lookAt(target);camera.updateProjectionMatrix();camera.updateMatrixWorld();const points=[];for(const x of [bounds.min.x,bounds.max.x])for(const y of [bounds.min.y,bounds.max.y])for(const z of [bounds.min.z,bounds.max.z])points.push(new T.Vector3(x,y,z).project(camera));if(points.every(p=>Math.abs(p.x)<.87&&Math.abs(p.y)<.78))break;distance*=1.07;}orbit.target.copy(target);}orbit.update();camera.updateProjectionMatrix();}window.addEventListener('resize',resize);
 renderer.setAnimationLoop(now=>{if(!opened)return;stream.visible=false;steam.forEach(p=>p.visible=false);jug.rotation.z=0;bottle.rotation.z=0;bottle.position.set(2.5,.75,-.4);ring.scale.setScalar((state.step===0?1.65:1)*(1+Math.sin(now*.004)*.07));if(animation){const t=Math.min(1,(now-animation.start)/1400),a=animation.action;if(a==='brew'){stream.visible=true;needle.rotation.z=-.55+Math.sin(t*Math.PI);liquid.position.y=.13+t*.11;}if(a==='milk'){jugmilk.visible=true;bottle.position.set(2.15,1.6,.8);bottle.rotation.z=.8;stream.visible=true;stream.material=milkmat;stream.position.set(1.55,1.6,.8);}if(a==='steam'){steam.forEach((p,i)=>{p.visible=true;p.position.y=1.3+((t*2+i*.12)%1.3);p.position.x=1.5+Math.sin(i+t*8)*.12;});jugmilk.scale.setScalar(1+DRINKS[state.drink].foam*t*.3);}if(a==='pour'){jug.position.set(.1,2,.65);jug.rotation.z=.75;stream.visible=true;stream.material=milkmat;stream.position.set(-.45,1.9,.5);liquid.position.y=.24+t*.25;}if(t===1){stream.visible=false;animation=null;jug.position.set(1.5,.77,.8);stream.material=brown;stream.position.set(-.7,1.9,.5);changed();renderUI();}}renderer.render(scene,camera);});
 window.RanchView?.register('coffeeStation',read,()=>{if(opened)renderer.render(scene,camera);});
 const empty={type:'object',properties:{}};
 window.RanchActions?.register('coffee',{revision:()=>revision,read,unavailable:action=>!opened&&!['open'].includes(action)?'Open the coffee shop first':animation&&['step','again'].includes(action)?'Current step is finishing':null,actions:{open:{description:'Enter the complete Level 1 coffee shop',schema:empty,run:open},close:{description:'Return to town square',schema:empty,run:()=>close('square')},view:{description:'View the full shop or working coffee counter',schema:{type:'object',properties:{view:{type:'string',enum:['shop','counter']}},required:['view'],additionalProperties:false},run:({view})=>focus(view)},hexes:{description:'Show human-sized hex scale',schema:{type:'object',properties:{visible:{type:'boolean'}},required:['visible'],additionalProperties:false},run:({visible})=>setHexes(visible)},hint:{description:'Repeat the spoken hint',schema:empty,run:hint},step:{description:'Perform the current recipe step',schema:{type:'object',properties:{action:{type:'string',enum:STEPS.map(s=>s.id)}},required:['action']},run:({action})=>act(action)},again:{description:'Make the next drink',schema:empty,run:again}}});
